code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    # Solid colored rectangles are the signal; isolated and scattered pixels are noise.
    # Permit sparse interruptions inside a rectangle, which are repaired to its color.
    candidates = []
    for color in set(v for row in grid for v in row if v != bg):
        for r0 in range(h):
            for r1 in range(r0+1,h):
                for c0 in range(w):
                    for c1 in range(c0+1,w):
                        area=(r1-r0+1)*(c1-c0+1)
                        cnt=sum(grid[r][c] == color for r in range(r0,r1+1) for c in range(c0,c1+1))
                        # Candidate must be substantially supported and not just a tiny noise pair.
                        if cnt >= max(4, int(area*.78 + .999)):
                            candidates.append((cnt/area, area, color, r0,r1,c0,c1))
    # Prefer large, well-supported rectangles. Smaller rectangles remain available for
    # separate objects; overlapping candidates may only write the same signal color.
    candidates.sort(key=lambda x:(x[0],x[1]), reverse=True)
    for purity, area, color, r0,r1,c0,c1 in candidates:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if grid[r][c] == color or out[r][c] == bg:
                    out[r][c]=color
    return out
